// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }

    function testFuzz_property(address caller) public {
        if (caller == address(0)) caller = address(1);

        address canonicalOwner = c.owner();

        address returnedWhenCalledAsCaller;
        vm.prank(caller);
        returnedWhenCalledAsCaller = c.owner();

        assertTrue(returnedWhenCalledAsCaller == canonicalOwner);
    }
}
